create function af_private.asset_deletable(p_path text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.af_projects p where p.id=af_private.storage_project(p_path) and p.org_id::text=split_part(p_path,'/',1) and af_private.role_for(p.org_id) in ('admin','member') and af_private.writable(p.org_id)) and not exists(select 1 from public.af_versions v where v.path=p_path)$$;revoke all on function af_private.asset_deletable(text) from public,anon;grant execute on function af_private.asset_deletable(text) to authenticated;drop policy agencyflow_storage_orphan_delete on storage.objects;create policy agencyflow_storage_orphan_delete on storage.objects for delete to authenticated using(bucket_id='agencyflow-designs' and owner_id=(select auth.uid())::text and af_private.asset_deletable(name));
